import { useState } from "react";
import AiSearchInput from "./AiSearchInput";
import AiLoader from "./AiLoader";
import { sendMessageToChat } from "../api/chat";
import { Check, ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

export default function AiSearchSection() {
    const [status, setStatus] = useState<"idle" | "loading" | "success" | "expanded">("idle");
    const [response, setResponse] = useState<string | null>(null);

    const handleSearch = async (query: string) => {
        if (status === "loading") return;
        if (!query.trim()) return;
        setStatus("loading");
        setResponse(null);

        try {
            const message = await sendMessageToChat(query);
            setResponse(message);
            setStatus("success");
        } catch (error) {
            console.error("Error searching:", error);
            setStatus("idle");
        }
    };

    const toggleExpand = () => {
        if (status === "success") {
            setStatus("expanded");
        } else if (status === "expanded") {
            setStatus("success");
        }
    };

    return (
        <div className="max-w-[1280px] mx-auto mb-20">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
                {/* Left Side: Text */}
                <div className="space-y-6">
                    <h2 className="text-4xl md:text-5xl font-bold text-white tracking-tight leading-tight">
                        Entenda o que posso
                        <br />
                        fazer por você
                    </h2>
                    <br />
                    <p className="text-white/60 text-lg leading-relaxed max-w-lg">
                        Apresento o Zé, meu agente de IA personalizado. Ele centraliza
                        informações sobre minha formação, projetos, stack de tecnologias e
                        serviços que ofereço. Desenvolvido com princípios de engenharia de
                        prompts e automação inteligente, o Zé foi criado para tornar sua
                        navegação mais eficiente. Pergunte o que quiser.
                    </p>
                </div>

                {/* Right Side: Interactive Component */}
                <div className="flex flex-col items-center w-full relative transition-all duration-500 pt-2">
                    {/* Search Bar */}
                    <div className="w-full max-w-md z-10">
                        <AiSearchInput onSearch={handleSearch} disabled={status === "loading"} />
                    </div>

                    <div className="flex flex-col items-center w-full max-w-md transition-all duration-500 mt-2 min-h-[300px] justify-center">
                        {status === "idle" && (
                            <div className="relative w-full aspect-square max-w-[250px] mx-auto">
                                <img
                                    src="data:image/png;base64,"
                                    alt="AI Assistant"
                                    className="w-full h-full object-contain"
                                />
                            </div>
                        )}

                        {status === "loading" && (
                            <div className="flex items-center justify-center w-full h-[300px]">
                                <AiLoader />
                            </div>
                        )}

                        {(status === "success" || status === "expanded") && (
                            <div className="flex flex-col items-center justify-center w-full space-y-6 animate-in fade-in zoom-in duration-500">
                                {status === "success" ? (
                                    <>
                                        <div className="w-20 h-20 rounded-full bg-green-500/20 flex items-center justify-center border border-green-500/50 shadow-[0_0_30px_rgba(34,197,94,0.3)]">
                                            <Check className="w-10 h-10 text-green-500" strokeWidth={3} />
                                        </div>
                                        <p className="text-white/80 text-lg font-medium text-center">
                                            Clique no botão "ler mais" para ver a resposta!
                                        </p>
                                    </>
                                ) : (
                                    <div className="w-full bg-white/5 border border-white/10 rounded-2xl p-6 md:p-8 backdrop-blur-sm">
                                        <div className="prose prose-invert max-w-none">
                                            <p className="text-white/90 text-lg leading-relaxed whitespace-pre-wrap">
                                                {response}
                                            </p>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Ler mais Button */}
                    {(status === "success" || status === "expanded") && (
                        <button
                            onClick={toggleExpand}
                            className={cn(
                                "flex flex-col items-center gap-2 text-white/60 hover:text-white transition-colors mt-4 group",
                                status === "expanded" && "mt-8"
                            )}
                        >
                            <span className="text-sm font-medium uppercase tracking-wider">
                                {status === "expanded" ? "Ler menos" : "Ler mais"}
                            </span>
                            <ChevronDown
                                className={cn(
                                    "w-6 h-6 transition-transform duration-300 group-hover:translate-y-1",
                                    status === "expanded" && "rotate-180"
                                )}
                            />
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
}
